# No-labels recall@5: chunk nguon = positive label
# (citation-as-weak-label, xem Sec 9)
def recall_at_k(collection, pseudo_queries, k=5):
hits = 0
for query, source_chunk_id in pseudo_queries:
res = collection.query(query_texts=[query], n_results=k)
if source_chunk_id in res["ids"][0]:
hits += 1
return hits / len(pseudo_queries)

# pseudo_queries: nho LLM sinh 1-3 cau hoi CHO TUNG chunk,
# chi dua tren noi dung chunk do -> chunk do la positive

Đây là floor check, không thay thế nhãn thật: câu hỏi do LLM sinh bám sát văn phong của chunk gốc, nên recall đo được thường cao hơn recall thực tế khi user diễn đạt lại.

from google.adk import Agent
class SafeAgent(Agent):
def before_model(self, request):
if detect_injection(request.text):
return block_response()
return request
def after_model(self, response):
if not safety_check(response.text):
return safe_fallback()
return response
def before_tool(self, tool_call):
return validate_args(tool_call)
def after_tool(self, tool_result):
return redact_pii(tool_result)

4 hooks = 4 điểm kiểm soát:

- before_model: validate input trước khi gửi LLM

- after_model: check output trước khi trả user

- before_tool: validate tool arguments

- after_tool: redact sensitive data từ tool results

Ưu điểm
Framework-native → không cần external service.

Fine-grained control tại mọi điểm trong pipeline.

Easy to test: mock hooks, unit test riêng.

